/**
 * Registro de Glifos do Design System Tik Tooria.
 *
 * IMPORTANTE: todo o dado vetorial abaixo foi copiado literalmente dos exports
 * SVG do arquivo Figma "TikTok UI Screens (Community) - cópia" (fileKey
 * `UIYCB87CQkpFwf1aWTBl1a`, página `4:171`). Nenhum caminho foi desenhado à
 * mão, aproximado ou substituído por outra biblioteca de ícones. O `viewBox`
 * original é preservado — não normalizado para 24×24 — de modo que as
 * proporções sejam idênticas às do arquivo de design.
 *
 * Para adicionar um glifo novo: exporte o SVG do Figma, copie os atributos
 * (`d`, `cx/cy/r`, `x/y/width/height`) sem edição e registre `figmaName`,
 * `viewBox` e `usage`.
 *
 * Convenção de cor: glifos monocromáticos declaram os caminhos sem `fill`, de
 * modo a herdarem `currentColor` e responderem à prop `tone`. Glifos que o
 * arquivo pinta com mais de uma cor (coração, comentário, seta de
 * compartilhamento, botão de seguir, selo verificado, bateria) preservam as
 * cores literais e ignoram `tone`.
 */

/**
 * Formas vetoriais suportadas por um glifo.
 */
export type TikIconShape =
  | {
      type: 'path';
      /** Atributo `d` literal do export do Figma */
      d: string;
      /** Aplica `fill-rule="evenodd"` quando verdadeiro */
      evenOdd?: boolean;
      /** Cor fixa; quando ausente, herda `currentColor` */
      fill?: string;
      /** Remove o preenchimento (caminho apenas com traço) */
      noFill?: boolean;
      stroke?: string;
      strokeWidth?: number;
      strokeLinecap?: 'butt' | 'round' | 'square';
    }
  | {
      type: 'circle';
      cx: number;
      cy: number;
      r: number;
      fill?: string;
      noFill?: boolean;
      stroke?: string;
      strokeWidth?: number;
    }
  | {
      type: 'ellipse';
      cx: number;
      cy: number;
      rx: number;
      ry: number;
      fill?: string;
      /** `transform` literal do export, quando o nó é rotacionado */
      transform?: string;
    }
  | {
      type: 'rect';
      x: number;
      y: number;
      width: number;
      height: number;
      rx?: number;
      fill?: string;
      noFill?: boolean;
      stroke?: string;
      strokeWidth?: number;
    };

/**
 * Definição completa de um glifo do Tik Tooria.
 */
export interface TikIconDefinition {
  /** Nome da camada correspondente no Figma */
  figmaName: string;
  /** Node do Figma de origem */
  figmaNode: string;
  /** viewBox original preservando a proporção exata do export */
  viewBox: string;
  /** Uso do glifo no produto */
  usage: string;
  /** Verdadeiro quando o glifo tem cores fixas e ignora a prop `tone` */
  multicolor?: boolean;
  /** Formas vetoriais que compõem o glifo */
  shapes: TikIconShape[];
}

