/**
 * Nome de um glifo da biblioteca oficial.
 */
export type TikIconName = keyof typeof tikIcons;

/**
 * Visão tipada do registro, usada pelo componente `Icon`.
 *
 * `tikIcons` é declarado com `satisfies` para que `TikIconName` seja a união
 * literal dos nomes; esta constante alarga o valor para a interface comum, de
 * modo que campos opcionais como `multicolor` sejam legíveis em qualquer glifo.
 */
export const tikIconRegistry: Record<TikIconName, TikIconDefinition> = tikIcons;

/**
 * Lista ordenada dos nomes de glifo, usada pela estória de Ícones.
 */
export const tikIconNames = Object.keys(tikIcons) as TikIconName[];
